custom_css:
/* ======森系蕾丝相框 ======by玥 */

/* 字体引入区 */
@import url("https://fontsapi.zeoseven.com/237/main/result.css"); /* 全局字体: 香脆大字 */
@import url("https://fontsapi.zeoseven.com/451/main/result.css"); /* 特殊字体: 纳诺孔黑 */

/* =全局字体设置= */
body {
    font-family: "XiangcuiDazijitiW15", sans-serif !important;
    font-weight: normal !important;
}

/* 整体聊天容器 */
.mes {
    position: relative !important;
    display: flex !important;
    flex-direction: column !important;
    align-items: center !important;
    margin-bottom: 30px !important;
    padding-top: 0 !important;
}

/* 头像容器 */
.mesAvatarWrapper {
    background: none !important;
    width: 370px !important;
    max-width: 100% !important;
    aspect-ratio: 11.5 / 10 !important;
    position: relative !important;
    margin: 0 auto 10px auto !important;
    z-index: 5 !important;
    overflow: visible !important;
    display: block !important;
}

/* 头像框 */
.mesAvatarWrapper::after {
    content: '' !important;
    position: absolute !important;
    top: 0; left: 0; width: 100%; height: 100%;
    background-image: url('https://i.postimg.cc/fb1yvw8L/tu-ceng-2.png') !important;
    background-size: 100% 100% !important;
    background-repeat: no-repeat !important;
    z-index: 5 !important;
    pointer-events: none !important;
}

/* 头像图片 */
.mes .avatar {
    position: absolute !important;
    top: 9.5% !important;
    left: 5.5% !important;
    width: 85% !important;
    aspect-ratio: 9 / 6 !important;
    height: auto !important;
    border-radius: 0 !important;
    border: none !important;
    padding: 0 !important;
    margin: 0 !important;
    z-index: 1 !important;
}

.mes .avatar img {
    width: 100% !important;
    height: 100% !important;
    object-fit: cover !important;
    object-position: top center !important;
}

/* 信息栏容器 */
.mes_info_bar {
    position: static !important;
    display: contents !important;
    background: transparent !important;
    border: none !important;
}

/* 头像容器 - 加上相对定位作为基准 */
.mesAvatarWrapper {
    background: none !important;
    width: 850px !important;
    max-width: 100% !important;
    aspect-ratio: 11.5 / 10 !important;
    position: relative !important;  /* 这个很重要 */
    margin: 0 auto 10px auto !important;
    z-index: 5 !important;
    overflow: visible !important;
    display: block !important;
}

/* 楼层号通用 */
.mes .mesIDDisplay {
    display: block !important;
    position: absolute !important;
    z-index: 60 !important;
    font-weight: bold !important;
    text-shadow: 1px 1px 0 #fff !important;
    text-align: right !important;
    pointer-events: none !important;
    background: transparent !important;
    border: none !important;
    top: 80% !important;
    right: 10% !important;
    font-size: 12px !important;
}

.mes[is_user="false"] .mesIDDisplay { color: #3a5f34 !important; }
.mes[is_user="true"] .mesIDDisplay { color: #d2691e !important; }

.mes .mesIDDisplay::before { content: '相识 ' !important; }
.mes .mesIDDisplay::after { content: ' 天' !important; }

/* 计时器通用 */
.mes .mes_timer {
    display: block !important;
    position: absolute !important;
    z-index: 60 !important;
    text-shadow: 1px 1px 0 #fff !important;
    text-align: right !important;
    pointer-events: none !important;
}

.mes[is_user="false"] .mes_timer {
    top: 87% !important;
    right: 7% !important;
    color: #3a5f34 !important;
    font-size: 13px !important;
}

.mes[is_user="false"] .mes_timer::after { content: '后成熟' !important; }
.mes[is_user="true"] .mes_timer { display: none !important; }

/* Token计数通用 */
.mes .tokenCounterDisplay,
.mes .mes_token_count {
    display: block !important;
    position: absolute !important;
    z-index: 60 !important;
    font-weight: bold !important;
    text-shadow: 1px 1px 0 #fff !important;
    text-align: right !important;
    pointer-events: none !important;
    background: transparent !important;
    font-size: 12px !important;
}

.mes[is_user="false"] .tokenCounterDisplay,
.mes[is_user="false"] .mes_token_count {
    top: 94% !important;
    right: 6% !important;
    color: #3a5f34 !important;
}

.mes[is_user="true"] .tokenCounterDisplay,
.mes[is_user="true"] .mes_token_count {
    top: 87% !important;
    right: 8% !important;
    color: #d2691e !important;
}

.mes .tokenCounterDisplay::before,
.mes .mes_token_count::before { content: '浇了 ' !important; }

.mes .tokenCounterDisplay::after,
.mes .mes_token_count::after { content: ' 的水' !important; }

/* 时间戳隐藏 */
.mes .timestamp { display: none !important; }

/* 全局聊天区域背景 - 半透明浅绿 */
#chat {
    background-color: rgba(200, 230, 201, 0.1) !important;
    background-image: none !important;
}

/* 气泡容器 */
.mes .mes_block {
    position: relative !important;
    margin-top: 60px !important;  /* 给名字留空间 */
    max-width: 100% !important;
    overflow: visible !important;  
    background-color: transparent !important;
    border: none !important;
    padding: 15px !important;
}

/* 名字 */
.mes .name_text {
    display: block !important;
    position: absolute !important;
    z-index: 60 !important;
    font-weight: 900 !important;
    text-shadow: 2px 2px 0 #fff, -1px -1px 0 #fff !important;
    pointer-events: none !important;
    white-space: nowrap !important;

    top: -115px !important;  /* 飞到气泡上方 */
    left: 50% !important;
    transform: translateX(-50%) !important;

    font-size: 20px !important;
    text-align: center !important;
}

.mes[is_user="false"] .name_text {
    color: #556b2f !important;
}

.mes[is_user="true"] .name_text {
    color: #8b4513 !important;
}

/* UI面板 (绿野仙踪铃兰版)  */
#world_info_container,
#preset_manager,
.list-group,
.card,
.card-body,
#bg_menu_content,
.extensions_block,
#completion_prompt_manager,
#completion_prompt_manager #completion_prompt_manager_list {
    background: transparent !important;
    background-color: transparent !important;
    border: none !important;
    box-shadow: none !important;
    padding: 0 !important;
    margin: 0 !important;
}
.list-group-item,
.world_info_entry,
.bias-item,
li.list-group-item {
    background-color: rgba(240, 248, 240, 0.85) !important;
    border: none !important;
    box-shadow: 0 2px 6px rgba(85, 130, 85, 0.15) !important;

    margin-bottom: 5px !important;
    margin-top: 2px !important;
    border-radius: 10px !important;
    padding: 6px 8px !important;
    color: #2d4a2d !important; /* 深森林绿 */
}

/* --- 3. 预设/提示词面板 */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
    display: flex !important;
    align-items: center !important;
    justify-content: flex-start !important;
    gap: 8px !important;
    background-color: rgba(245, 255, 250, 0.9) !important;
    background-image: radial-gradient(circle, rgba(85, 130, 85, 0.15) 1px, transparent 1px) !important;
    background-size: 12px 12px !important;

    border: none !important;
    border-radius: 10px !important;
    margin-bottom: 6px !important;
    padding: 8px 12px !important;

    color: #2d4a2d !important;
}

/* 文字层 */
#completion_prompt_manager .completion_prompt_manager_prompt_name {
    flex: 1 !important;
    text-align: left !important;
    white-space: nowrap !important;
    overflow: hidden !important;
    text-overflow: ellipsis !important;

    font-size: 13px !important;
    color: #2d4a2d !important;
    font-weight: bold !important;
    opacity: 1 !important;
    text-shadow: none !important;
}

/* 悬停 */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt:hover {
    background-color: rgba(255, 255, 255, 0.95) !important;
    transform: translateX(3px);
    box-shadow: 0 3px 8px rgba(85, 130, 85, 0.2) !important;
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt:hover .completion_prompt_manager_prompt_name {
    color: #1a331a !important;
}
.completion_prompt_manager_prompt_actions {
    display: flex !important;
    gap: 5px !important;
    margin-left: auto !important;
}

/* 强制预设名称文字可见 */
#completion_prompt_manager .completion_prompt_manager_prompt_name,
#completion_prompt_manager_list li span,
#completion_prompt_manager_list li .completion_prompt_manager_prompt_name,
.completion_prompt_manager_prompt .completion_prompt_manager_prompt_name {
    color: #2d4a2d !important;
    -webkit-text-fill-color: #2d4a2d !important;
    opacity: 1 !important;
    visibility: visible !important;
}

/*  输入框/搜索框/文本域/下拉菜单 */
input[type="text"],
input[type="search"],
textarea,
select,
.text_pole {
    background-color: rgba(245, 255, 250, 0.95) !important;
    background-image: radial-gradient(circle, rgba(85, 130, 85, 0.12) 1px, transparent 1px) !important;
    background-size: 10px 10px !important;
    color: #2d4a2d !important;
    border: none !important;

    border-radius: 8px !important;
    margin: 2px 0 !important;
    padding: 8px 12px !important;
    box-shadow: inset 0 1px 3px rgba(85, 130, 85, 0.1) !important;
}
input:focus, textarea:focus, select:focus {
    box-shadow: 0 0 10px rgba(85, 130, 85, 0.35) !important;
    background-color: rgba(255, 255, 255, 0.58) !important;
}

/* 折叠按钮 (Toggle Bars) - 铃兰版 --- */
.inline-drawer-toggle,
.inline-drawer-header {
    background-color: rgba(245, 255, 250, 0.62) !important;
    border: none !important;
    border-radius: 12px !important;
    box-shadow: 0 2px 6px rgba(85, 130, 85, 0.62) !important;

    background-image: none !important;
    color: #2d4a2d !important;
    font-weight: bold;
    margin-bottom: 5px !important;
    padding: 8px 12px !important;
    display: flex;
    align-items: center;
}

/* 滑动条森林轨道 + 铃兰滑块) */

input[type="range"]::-webkit-slider-runnable-track {
    height: 8px !important;
    background: linear-gradient(90deg, #c8e6c9, #a5d6a7) !important;
    border: none !important;
    border-radius: 18px !important;
}

input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none;
    height: 42px;
    width: 42px;
    margin-top: -16px;
    background-image: url('https://i.postimg.cc/3w8kt853/mmexport1768977594355.gif') !important;
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    background-color: transparent;
    border: none;
    cursor: pointer;
}
input[type="range"]::-moz-range-thumb {
    height: 36px;
    width: 36px;
    background-image: url('https://i.postimg.cc/3w8kt853/mmexport1768977594355.gif') !important;
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    background-color: transparent;
    border: none;
    cursor: pointer;
}

/* 复选框 (森林绿圆圈 + 仙人掌) */
input[type="checkbox"],
input[type="checkbox"]::before,
input[type="checkbox"]::after {
    appearance: none !important;
    -webkit-appearance: none !important;
    -moz-appearance: none !important;
}

input[type="checkbox"] {
    width: 22px !important;
    height: 22px !important;
    outline: none !important;
    cursor: pointer;

    /* 未选中：薄荷底 */
    background-color: rgba(200, 230, 201, 0.8) !important;
    background-image: none !important;
    border: none !important;
    border-radius: 50% !important;
    transition: all 0.2s ease;
    box-shadow: inset 0 1px 3px rgba(85, 130, 85, 0.2) !important;
}

/* 清除伪元素的对勾 */
input[type="checkbox"]::before,
input[type="checkbox"]::after,
input[type="checkbox"]:checked::before,
input[type="checkbox"]:checked::after {
    content: none !important;
    display: none !important;
    background: none !important;
    background-image: none !important;
}

/* 选中状态 */
input[type="checkbox"]:checked {
    background-color: rgba(85, 130, 85, 0.2) !important;
    background-image: url('https://i.postimg.cc/XqtZLm9x/mmexport1768979406639.gif') !important;
    background-size: 100% !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
}
/* --- 全局侧边栏背景 */
.drawer-content,
#table_drawer_content,
#extensions_settings {
    background-image: url('https://i.postimg.cc/GpmFS0ZJ/Image_1768977745168_391.jpg') !important;
    background-size: cover !important;
    background-position: center !important;
    background-repeat: no-repeat !important;
    background-color: #f0f8f0 !important;
    border: none !important;
}

/* 标题栏折叠栏*/
.sub_block_title,
.standoutHeader,
#user-settings-block h4,
#extensions_settings h4,
.WorldInfoContent .h4,
h3, h4, h5 {
    background-color: rgba(245, 255, 250, 0.4) !important;
    border: none !important;
    box-shadow: 0 2px 6px rgba(85, 130, 85, 0.4) !important;

    border-radius: 10px !important;
    margin: 6px 0 !important;
    padding: 8px 12px !important;
    color: #2d4a2d !important;
    font-weight: bold !important;
    text-shadow: none !important;

    /* 铃兰装饰 */
    background-image: url('https://i.postimg.cc/3w8kt853/mmexport1768977594355.gif') !important;
    background-repeat: no-repeat !important;
    background-position: right 10px center !important;
    background-size: auto 100% !important;

    /* 排版修正 */
    padding-right: 50px !important;
    display: flex !important;
    align-items: center !important;
    min-height: 38px !important;
}

h3 span, h4 span {
    flex: 1;
}

/* --按钮样式 -- */
button, .menu_button {
    background-color: rgba(165, 214, 167, 0.85) !important;
    border: none !important;
    border-radius: 8px !important;
    color: #2d4a2d !important;
    padding: 6px 12px !important;
    transition: all 0.2s ease;
}

button:hover, .menu_button:hover {
    background-color: rgba(129, 199, 132, 0.95) !important;
    transform: translateY(-1px);
    box-shadow: 0 3px 8px rgba(85, 130, 85, 0.2) !important;
}

/* 顶栏美化（绿野仙踪爱心版） = */
#top-settings-holder {
    background: transparent !important;
    background-color: transparent !important;
    border: none !important;
    box-shadow: none !important;
    position: relative !important;
    overflow: visible !important;
}

/* 左侧装饰 */
#top-settings-holder::before {
    content: '';
    position: absolute;
    top: 180%;
    left: -5px;
    transform: translateY(-50%);
    width: 50px;
    height: 60px;
    background-image: url('https://i.postimg.cc/RVBYFFkQ/tu-ceng-4.png');
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    pointer-events: none;
    z-index: 100;
}
#top-settings-holder .drawer-icon::before {
    content: '' !important;
    visibility: hidden !important;
}
#top-settings-holder .drawer {
    flex: 1;
}
#top-settings-holder .drawer-icon {
    display: block !important;
    margin: 0 auto !important;
    background-image: url('https://i.postimg.cc/9Qt4P4SR/mmexport1768977606766.gif') !important;
    background-size: contain !important;
    background-position: center !important;
    background-repeat: no-repeat !important;
    width: 35px !important;
    height: 35px !important;
    opacity: 1 !important;
    transition: transform 0.4s cubic-bezier(0.68, -0.55, 0.265, 1.55) !important;
}
#top-settings-holder .drawer-icon:hover {
    transform: scale(1.35) !important;
}
#top-settings-holder .drawer-icon:active {
    animation: heartBounce 0.4s ease !important;
}
@keyframes heartBounce {
    0% { transform: scale(1); }
    30% { transform: scale(1.5); }
    50% { transform: scale(0.9); }
    70% { transform: scale(1.15); }
    100% { transform: scale(1.1); }
}
#top-settings-holder .drawer .drawer-icon.openIcon {
    transform: scale(1.1) !important;
    animation: heartBounce 0.5s ease !important;
}

/* 底栏美化（绿野仙踪像素版） */
#form_sheld,
#send_form {
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
    position: relative !important;
    overflow: visible !important;
}

/* 底栏图标像素风 */

#form_sheld i[class*="fa-"],
#form_sheld [class*="fa-"]::before,
#send_form i[class*="fa-"],
#send_form [class*="fa-"]::before,
#leftSendForm i,
#leftSendForm i::before,
#rightSendForm i,
#rightSendForm i::before,
.mes_send i,
.mes_send i::before,
#options_button i,
#options_button i::before,
#options_button .fa,
#options_button .fa::before,
#extensionsMenuButton i,
#extensionsMenuButton i::before,
#extensionsMenuButton .fa,
#extensionsMenuButton .fa::before,
#qr--bar i,
#qr--bar i::before,
#qr--bar .fa,
#qr--bar .fa::before,
#mes_stop i,
#mes_stop i::before,
#mes_stop .fa,
#mes_stop .fa::before,
.qr--button i,
.qr--button i::before {
    color: #78a355 !important;
    -webkit-text-stroke: 0.7px #D2EECD !important;

    /* 像素风阴影*/
    text-shadow:
        1px 1px 0 #2d4a2d,
        -1px -1px 0 rgba(255, 255, 255, 0.2),
        2px 2px 0 rgba(45, 74, 45, 0.1) !important;
    -webkit-font-smoothing: none !important;
    -moz-osx-font-smoothing: unset !important;
    image-rendering: pixelated !important;

    opacity: 1 !important;
    visibility: visible !important;
    font-size: 20px !important;
    transition: transform 0.3s cubic-bezier(0.68, -0.55, 0.265, 1.55) !important;
}

/* 发送按钮 - 小兔子图片  */
#send_but i,
#send_but i::before,
#send_but .fa,
#send_but .fa::before,
#send_but [class*="fa-"],
#send_but [class*="fa-"]::before {
    visibility: hidden !important;
    opacity: 0 !important;
    font-size: 0 !important;
    width: 0 !important;
    height: 0 !important;
}

#send_but {
    position: relative !important;
    min-width: 40px !important;
    min-height: 40px !important;
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
}
#send_but::after {
    content: '' !important;
    position: absolute !important;
    top: 50% !important;
    left: 50% !important;
    transform: translate(-50%, -50%) !important;

    width: 40px !important;
    height: 38px !important;
    background-image: url('https://i.postimg.cc/Y06bg54G/tu-ceng-5.png') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    image-rendering: pixelated !important;

    pointer-events: none !important;
    z-index: 10 !important;
    transition: transform 0.4s cubic-bezier(0.68, -0.55, 0.265, 1) !important;
}

/*  消息操作区✏️ = */

.mes_button,
.mes_edit_buttons button,
.extraMesButtons .mes_button {
    background: transparent !important; 
    border: none !important;
    box-shadow: none !important;
    opacity: 0.7 !important; 

    transition: transform 0.3s cubic-bezier(0.68, -0.55, 0.265, 1.55), opacity 0.2s !important;
    margin: 0 2px !important; 
}
/* 小铅笔、三个点、删除、重生成图标 */
.mes_button i, 
.mes_button::before,
.mes_button [class*="fa-"],
.mes_edit_buttons button i,
.extraMesButtons .mes_button i {
    color: #78a355 !important; 
    -webkit-text-stroke: 0.6px #D2EECD !important; 
    text-shadow:
        1px 1px 0 #2d4a2d,
        -1px -1px 0 rgba(255, 255, 255, 0.2),
        2px 2px 0 rgba(45, 74, 45, 0.1) !important;
    -webkit-font-smoothing: none !important;
    -moz-osx-font-smoothing: unset !important;
    image-rendering: pixelated !important;
    font-size: 16px !important; 
}
.mes_button:hover,
.mes_edit_buttons button:hover,
.extraMesButtons .mes_button:hover {
    opacity: 1 !important;
    transform: scale(1.2) translateY(-2px) !important; 
    filter: brightness(1.1) !important;
}

.extraMesButtons {
    background-color: #f4fcf2 !important; 

    border: 2px solid #4a7c4e !important; 
    border-radius: 8px !important;
    box-shadow: 4px 4px 0 rgba(45, 74, 45, 0.2) !important;

    padding: 5px !important;
    gap: 5px !important; 
}
.extraMesButtons .mes_button {
    border-radius: 4px !important;
    width: 28px !important;
    height: 28px !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
}
.extraMesButtons .mes_button:hover {
    background-color: #D2EECD !important; 
}

/* 消息切换：绿野仙踪像素版==== */

.swipe_left, 
.swipe_right {
    background-image: none !important; 
    color: #4a7c4e !important;
    font-size: 24px !important;
    -webkit-text-stroke: 0.7px #D2EECD !important;
    text-shadow: 1px 1px 0 #2d4a2d, 2px 2px 0 rgba(45, 74, 45, 0.1) !important;
    transition: transform 0.3s cubic-bezier(0.68, -0.55, 0.265, 1.55) !important;
    opacity: 0.5 !important; 
}
.swipe_left:hover, 
.swipe_right:hover {
    opacity: 1 !important;
    transform: scale(1.3) !important; 
}

/* ==思维链简约版 === */
.mes_reasoning_header {
    color: transparent !important;
    font-size: 0 !important;
    background-color: #f4fcf2 !important; 
    border: 2px solid #4a7c4e !important; 
    border-radius: 6px !important;        
    min-height: 35px !important;
    margin: 10px 0 5px 0 !important;
    padding: 0 !important;

    display: flex !important;
    align-items: center !important;
    justify-content: center !important;

    cursor: pointer;
    transition: all 0.2s ease !important;
